import java.io.InputStream;
import java.io.OutputStream;
import java.io.PrintWriter;
import java.util.InputMismatchException;

public class Main3 {
    public static void main(String[] args) {
        InputStream is = System.in;
        OutputStream os = System.out;
        BufferedInput in = new BufferedInput(is);
        PrintWriter out = new PrintWriter(os);
        Algorithm alg = new Algorithm();
        alg.run(1, in, out);
        out.close();
    }

    static class Algorithm {
        static final int MAX_LEN = 1 << 20;
        static double[] cCos = new double[MAX_LEN];
        static double[] cSin = new double[MAX_LEN];
        static double[] cConjCos = new double[MAX_LEN];
        static double[] cConjSin = new double[MAX_LEN];

        static {
            for (int size = 1; size <= cCos.length; size <<= 1) {
                int half = size >> 1;
                for (int i = half; i < size; i++) {
                    double angle = 2 * Math.PI * (i - half) / size;
                    cCos[i] = Math.cos(angle);
                    cSin[i] = Math.sin(angle);
                    cConjCos[i] = Math.cos(-angle);
                    cConjSin[i] = Math.sin(-angle);
                }
            }
        }

        void run(int testIdx, BufferedInput reader, PrintWriter writer) {
            final int MOD = 998244353;
            int n = reader.readInteger();
            int k = reader.readInteger();
            int[] baseVector = new int[10];
            for (int i = 0; i < k; i++) {
                int idx = reader.readInteger();
                baseVector[idx] = 1;
            }

            int[] currentResult = {1};
            int exp = n / 2;

            while (true) {
                if ((exp & 1) != 0) {
                    currentResult = polyMultiply(currentResult, baseVector, MOD);
                }
                exp >>= 1;
                if (exp == 0) break;
                baseVector = polyMultiply(baseVector, baseVector, MOD);
            }

            long sum = 0;
            for (int x : currentResult) {
                sum += (long) x * x;
            }
            writer.println(sum % MOD);
        }

        int[] polyMultiply(int[] A, int[] B, int mod) {
            int requiredLen = A.length + B.length - 1;
            int n = Math.max(2, Integer.highestOneBit(requiredLen - 1) << 1);

            double[] ar = new double[n];
            double[] ai = new double[n];
            for (int i = 0; i < A.length; i++) {
                int val = ((A[i] % mod) + mod) % mod;
                ar[i] = val & ((1 << 15) - 1);
                ai[i] = val >>> 15;
            }
            transform(ar, ai, false);

            double[] br = new double[n];
            double[] bi = new double[n];
            for (int i = 0; i < B.length; i++) {
                int val = ((B[i] % mod) + mod) % mod;
                br[i] = val & ((1 << 15) - 1);
                bi[i] = val >>> 15;
            }
            transform(br, bi, false);

            double[] cr = new double[n];
            double[] ci = new double[n];

            for (int i = 0; i < n; i++) {
                int j = (n - i) & (n - 1);
                double a1r = (ar[i] + ar[j]) * 0.5;
                double a1i = (ai[i] - ai[j]) * 0.5;
                double a2r = (ai[i] + ai[j]) * 0.5;
                double a2i = (ar[j] - ar[i]) * 0.5;

                double b1r = (br[i] + br[j]) * 0.5;
                double b1i = (bi[i] - bi[j]) * 0.5;
                double b2r = (bi[i] + bi[j]) * 0.5;
                double b2i = (br[j] - br[i]) * 0.5;

                cr[i] = a1r * b1r - a1i * b1i - a2r * b2i - a2i * b2r;
                ci[i] = a1r * b1i + a1i * b1r + a2r * b2r - a2i * b2i;
            }

            transform(cr, ci, true);
            int[] output = new int[requiredLen];
            for (int i = 0; i < requiredLen; i++) {
                long p = Math.round(cr[i]);
                long q = Math.round(ci[i]);
                long r = Math.round(ci[n - i]);
                output[i] = (int) ((p + ((q % mod) << 15) + ((r % mod) << 30)) % mod);
            }
            return output;
        }

        void transform(double[] real, double[] imag, boolean isInverse) {
            int n = real.length;
            int bits = 32 - Integer.numberOfTrailingZeros(n);
            for (int i = 1; i < n; i++) {
                int j = Integer.reverse(i << bits) >>> bits;
                if (i < j) {
                    double temp = real[i]; real[i] = real[j]; real[j] = temp;
                    temp = imag[i]; imag[i] = imag[j]; imag[j] = temp;
                }
            }

            for (int len = 2; len <= n; len <<= 1) {
                int half = len >> 1;
                int step = cCos.length / len;

                for (int base = 0; base < n; base += len) {
                    for (int offset = 0, wIdx = 0; offset < half; offset++, wIdx += step) {
                        double wReal = isInverse ? cConjCos[half + offset] : cCos[half + offset];
                        double wImag = isInverse ? cConjSin[half + offset] : cSin[half + offset];

                        int idx1 = base + offset;
                        int idx2 = base + offset + half;

                        double uRe = real[idx1];
                        double uIm = imag[idx1];
                        double vRe = real[idx2] * wReal - imag[idx2] * wImag;
                        double vIm = real[idx2] * wImag + imag[idx2] * wReal;

                        real[idx1] = uRe + vRe;
                        imag[idx1] = uIm + vIm;
                        real[idx2] = uRe - vRe;
                        imag[idx2] = uIm - vIm;
                    }
                }
            }

            if (isInverse) {
                double invN = 1.0 / n;
                for (int i = 0; i < n; i++) {
                    real[i] *= invN;
                    imag[i] *= invN;
                }
            }
        }
    }

    static class BufferedInput {
        final InputStream in;
        final byte[] buf = new byte[1024];
        int idx = 0;
        int len = 0;

        BufferedInput(InputStream is) {
            this.in = is;
        }

        int readByte() {
            if (len == -1) throw new InputMismatchException();
            if (idx >= len) {
                idx = 0;
                try {
                    len = in.read(buf);
                } catch (Exception ex) {
                    throw new InputMismatchException();
                }
                if (len <= 0) return -1;
            }
            return buf[idx++] & 0xFF;
        }

        int readInteger() {
            int c = readByte();
            while (isSpace(c)) c = readByte();
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int res = 0;
            do {
                if (c < '0' || c > '9') throw new InputMismatchException();
                res = res * 10 + c - '0';
                c = readByte();
            } while (!isSpace(c));
            return res * sign;
        }

        boolean isSpace(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }
    }
}
